    ($SATQ$35e05e19$SATQ$, $SATQ$b4b30a03-7260-43d7-a5d1-c60b998baa85$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Advanced Math$SATQ$, $SATQ$P$SATQ$, $SATQ$P.C.$SATQ$, $SATQ$Nonlinear functions$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: left;">A park ranger hung squirrel houses each in the shape of a right rectangular prism for fox squirrels. Each house has a height of <math alttext="11"><mn>11</mn>
</math> inches. The length of each house's base is <math alttext="x"><mi>x</mi>
</math> inches, which is <math alttext="1"><mn>1</mn>
</math> inch more than the width of the house's base. Which function <math alttext="upper V"><mi>V</mi>
</math> gives the volume of each house, in cubic inches, in terms of the length of the house's base?</p>$SATQ$, $SATQ$[{"id":"ab654dae-f60b-43f7-a6a8-a081b2a59a3d","content":"<p><math alttext=\"upper V left parenthesis x right parenthesis equals 11 x left parenthesis x minus 1 right parenthesis\"><mi>V</mi><mfenced><mi>x</mi></mfenced><mo>=</mo><mn>11</mn><mi>x</mi><mfenced><mrow><mi>x</mi><mo>-</mo><mn>1</mn></mrow></mfenced></math></p>"},{"id":"70535ac2-f376-479d-8bcf-2dbcd9005850","content":"<p><math alttext=\"upper V left parenthesis x right parenthesis equals 11 x left parenthesis x plus 1 right parenthesis\"><mi>V</mi><mfenced><mi>x</mi></mfenced><mo>=</mo><mn>11</mn><mi>x</mi><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced></math></p>"},{"id":"05cf5f2d-2b59-4936-9b70-5c75a226cc48","content":"<p><math alttext=\"upper V left parenthesis x right parenthesis equals x left parenthesis x plus 11 right parenthesis left parenthesis x minus 1 right parenthesis\"><mi>V</mi><mfenced><mi>x</mi></mfenced><mo>=</mo><mi>x</mi><mfenced><mrow><mi>x</mi><mo>+</mo><mn>11</mn></mrow></mfenced><mfenced><mrow><mi>x</mi><mo>-</mo><mn>1</mn></mrow></mfenced></math></p>"},{"id":"0e6a7db9-5649-4b9b-b045-55a5505710e3","content":"<p><math alttext=\"upper V left parenthesis x right parenthesis equals x left parenthesis x plus 11 right parenthesis left parenthesis x plus 1 right parenthesis\"><mi>V</mi><mfenced><mi>x</mi></mfenced><mo>=</mo><mi>x</mi><mfenced><mrow><mi>x</mi><mo>+</mo><mn>11</mn></mrow></mfenced><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced></math></p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["ab654dae-f60b-43f7-a6a8-a081b2a59a3d"]$SATQ$::jsonb, $SATQ$<p style="text-align: left;">Choice A is correct. The volume of a prism is equal to the area of its base times its height.&nbsp;It's given that the length of each house's base is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="x"><mi>x</mi></math> inches and that this length is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="1"><mn>1</mn></math> inch more than the width, in inches, of the house's base. It follows that the width, in inches, of the house's base is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="x minus 1"><mi>x</mi><mo>-</mo><mn>1</mn></math>. The area of a rectangle is the product of its length and its width. Therefore, the area of the base of the house is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="x left parenthesis x minus 1 right parenthesis"><mi>x</mi><mo>(</mo><mi>x</mi><mo>-</mo><mn>1</mn><mo>)</mo></math> square inches. It's given that the height of each house is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="11"><mn>11</mn></math> inches. Therefore, the function <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="upper V"><mi>V</mi></math> that gives the volume of each house, in cubic inches, in terms of the length of the house's base <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="x"><mi>x</mi></math> is <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="upper V left parenthesis x right parenthesis equals x left parenthesis x minus 1 right parenthesis 11"><mi>V</mi><mo>(</mo><mi>x</mi><mo>)</mo><mo>=</mo><mi>x</mi><mo>(</mo><mi>x</mi><mo>-</mo><mn>1</mn><mo>)</mo><mn>11</mn></math>, or <math xmlns="http://www.w3.org/1998/Math/MathML" alttext="upper V left parenthesis x right parenthesis equals 11 x left parenthesis x minus 1 right parenthesis"><mi>V</mi><mo>(</mo><mi>x</mi><mo>)</mo><mo>=</mo><mn>11</mn><mi>x</mi><mo>(</mo><mi>x</mi><mo>-</mo><mn>1</mn><mo>)</mo></math>.</p>
<p style="text-align: left;">Choice B is incorrect&nbsp;and may result from conceptual or calculation errors.</p>
<p style="text-align: left;">Choice C is incorrect&nbsp;and may result from conceptual or calculation errors.</p>
<p style="text-align: left;">Choice D is incorrect and may result from conceptual or calculation errors.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"35e05e19","external_id":"b4b30a03-7260-43d7-a5d1-c60b998baa85","disclosed_item_id":null,"source":"qbank","vaultid":null,"uId":"3ccef813-589f-4823-a38d-d7608b852c9d","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"P","domain":"Advanced Math","skill_cd":"P.C.","skill_desc":"Nonlinear functions","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":null,"stem":"<p style=\"text-align: left;\">A park ranger hung squirrel houses each in the shape of a right rectangular prism for fox squirrels. Each house has a height of <math alttext=\"11\"><mn>11</mn>\n</math> inches. The length of each house's base is <math alttext=\"x\"><mi>x</mi>\n</math> inches, which is <math alttext=\"1\"><mn>1</mn>\n</math> inch more than the width of the house's base. Which function <math alttext=\"upper V\"><mi>V</mi>\n</math> gives the volume of each house, in cubic inches, in terms of the length of the house's base?</p>","answerOptions":[{"id":"ab654dae-f60b-43f7-a6a8-a081b2a59a3d","content":"<p><math alttext=\"upper V left parenthesis x right parenthesis equals 11 x left parenthesis x minus 1 right parenthesis\"><mi>V</mi><mfenced><mi>x</mi></mfenced><mo>=</mo><mn>11</mn><mi>x</mi><mfenced><mrow><mi>x</mi><mo>-</mo><mn>1</mn></mrow></mfenced></math></p>"},{"id":"70535ac2-f376-479d-8bcf-2dbcd9005850","content":"<p><math alttext=\"upper V left parenthesis x right parenthesis equals 11 x left parenthesis x plus 1 right parenthesis\"><mi>V</mi><mfenced><mi>x</mi></mfenced><mo>=</mo><mn>11</mn><mi>x</mi><mfenced><mrow><mi>x</mi><mo>+</mo><mn>1</mn></mrow></mfenced></math></p>"},{"id":"05cf5f2d-2b59-4936-9b70-5c75a226cc48","content":"<p><math alttext=\"upper V left parenthesis x right parenthesis equals x left parenthesis x plus 11 right parenthesis left parenthesis x mi